contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        bool reverted;
        address owner = c.smartfix_owner();
        uint256 balBefore = address(c).balance;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        if (msg.sender != owner) {
            assert(reverted && address(c).balance == balBefore);
        } else {
            assert(!reverted);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        address owner = c.smartfix_owner();
        require(owner == address(this));
        uint cBal = address(c).balance;
        uint balBefore = address(this).balance;
        c.sudicideAnyone();
        assert(address(this).balance == balBefore + cBal && address(c).balance == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        require(c.smartfix_owner() == address(this));
        uint cBal = address(c).balance;
        uint balBefore = address(this).balance;
        c.sudicideAnyone();
        assert(address(this).balance >= amount && address(this).balance == balBefore + cBal && address(c).balance == 0);
    }
    receive() external payable {}
}
